import { edit_user_app_access } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteadmins: Boolean,
    adminitems: Object,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_user_app_access, {
          input: {
            user_access: "RESTRICTED_USERS",
            action_type: "REMOVE",
            subscriber_id: this.adminitems.subscriber_id,
            dashboard_id: this.rowInfo.dashboard_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_user_app_access);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
